"""Derive SkyyWardrobe/build_skyywardrobe_0.2.9.py from the SET pin 0.2.8 (build_skyywardrobe_0.2.8.py, GENERATED by
tools/wardrobe_0_2_8_patch.py; 0.2.8 stays untouched) AND SkyyWardrobe/test_skyywardrobe_0.2.9.py from test_skyywardrobe_0.2.8.py.
Edit THIS file, never the generated scripts: python tools/wardrobe_0_2_9_patch.py, then python SkyyWardrobe/build_skyywardrobe_0.2.9.py
(never --deploy from an agent). Test: python SkyyWardrobe/test_skyywardrobe_0.2.9.py
Every anchor is asserted once; at the end every change is undone on a copy and compared with the source (nothing else changed).

0.2.9 (2026-10-17) = the FP1 review LOW "Requip deposit strands claimed food" (RESUME NEXT 1). SkyyCooking 0.1.11's Potion Flask / Food
Pouch auto-fill from main storage + backpack, and SkyySacks 0.8.18 (spec 2.3 "eating beats storing") leaves an id the Flask / Pouch claim
(bridge supply:fn:claims) in storage for them - in its sweep AND its Deposit all. Requip's Deposit all (/requip dump, the page button)
did not ask: it swept that food / those potions into the Requip pool (kind entries), past the Flask / Pouch that had claimed them - the
auto-fill never sees them again (they only come back by a Take out or a loadout kind pick).
  1. WdBridge.claimed(uuid, id, memo) = one supply:fn:claims ask {UUID, String id} -> TRUE only for Boolean.TRUE; missing key / a bad uuid /
     a Throwable = FALSE (warned once) = 0.2.8 behaviour; memo = one ask per distinct id per pass.
  2. WdTx.depAllSkip (Deposit all, NOT auto-store - that never takes potions / food): a PLAIN (metadata-free) stack in STORAGE or the
     BACKPACK whose id is claimed stays where it is (a "stayed out" reason: "the Potion Flask / Food Pouch takes your <name>"), exactly
     like SkyySacks 0.8.18. Unchanged on purpose (as Sacks): the single Deposit click (an explicit choice), hotbar stacks (deposit.hotbar:
     the Flask / Pouch never fill from the hotbar - a skipped hotbar stack would sit there), metadata stacks, Equip's Empty / pick deposits
     (the player picked that slot).
  No item moves on the new path (a skip is a no-move), so nothing can be lost or copied; no command, no bridge key, no saved-data change.
  Rollback to 0.2.8: safe (Deposit all pools claimed food again). Needs nothing new: SkyyCooking 0.1.11 publishes supply:fn:claims; without
  it (older / missing Cooking) nothing changes.
Classes: WdBridge (+ claimed), WdTx (depAllSkip body).
"""
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
HERE = os.path.join(ROOT, "SkyyWardrobe")
LF = "\n"


class Patch(object):
    def __init__(self, src, dst, tag):
        raw = open(src, "rb").read()
        self.nl = "\r\n" if b"\r\n" in raw else "\n"
        assert self.nl == "\n" or raw.count(b"\r\n") == raw.count(b"\n"), "mixed line endings in " + src
        self.s = raw.decode("utf8").replace("\r\n", "\n")
        self.old = self.s
        self.src, self.dst, self.tag = src, dst, tag
        self.changes = []

    def has(self, t):
        return t in self.s

    def rep(self, old, new):
        n = self.s.count(old)
        assert n == 1, "%s anchor count %d: %s" % (self.tag, n, old[:140])
        assert self.s.count(new) == 0, "%s: the new text already exists: %s" % (self.tag, new[:100])
        self.s = self.s.replace(old, new, 1)
        self.changes.append((new, old))

    def finish(self):
        u = self.s
        for new, old in reversed(self.changes):
            assert u.count(new) == 1, "%s: a change is not unique any more: %s" % (self.tag, new[:100])
            u = u.replace(new, old, 1)
        assert u == self.old, "%s: the generated script differs from the source outside the recorded changes" % self.tag
        compile(self.s, self.dst, "exec")
        open(self.dst, "w", encoding="utf8", newline="").write(self.s.replace(LF, self.nl) if self.nl != LF else self.s)
        print("wrote", os.path.relpath(self.dst, ROOT), "(%d lines; source %d; %d changes, undo-compare OK)" % (self.s.count(LF), self.old.count(LF), len(self.changes)))


# ====================================================================================================================== THE BUILD
P = Patch(os.path.join(HERE, "build_skyywardrobe_0.2.8.py"), os.path.join(HERE, "build_skyywardrobe_0.2.9.py"), "build")
assert P.has('VERSION = "0.2.8"\n') and P.has("builtinKeep") and not P.has("supply:fn:claims"), "the source must be the generated build_skyywardrobe_0.2.8.py"
REG0, SYS0 = P.s.count("registerCommand("), P.s.count("registerSystem(")

P.rep('"""SkyyWardrobe 0.2.8 "Requip" - build script GENERATED by tools/wardrobe_0_2_8_patch.py from build_skyywardrobe_0.2.7.py (edit the patch).\n',
      '"""SkyyWardrobe 0.2.9 "Requip" - build script GENERATED by tools/wardrobe_0_2_9_patch.py from build_skyywardrobe_0.2.8.py (edit the patch).\n'
      '0.2.9 (2026-10-17, FP1 review LOW; full notes: tools/wardrobe_0_2_9_patch.py): Deposit all leaves a plain storage / backpack stack the\n'
      'Potion Flask / Food Pouch claim (SkyyCooking 0.1.11 supply:fn:claims, asked once per id) for them - as SkyySacks 0.8.18 does.\n'
      'Test: python SkyyWardrobe/test_skyywardrobe_0.2.9.py\n'
      '0.2.8 = GENERATED by tools/wardrobe_0_2_8_patch.py from build_skyywardrobe_0.2.7.py.\n')
P.rep('VERSION = "0.2.8"\n', 'VERSION = "0.2.9"\n')
P.rep('''M(brg, "public static boolean backHas() { return @PKG@.WdLog.fn(\\"sacks:fn:deposit\\") != null; }")\n''',
      '''M(brg, "public static boolean backHas() { return @PKG@.WdLog.fn(\\"sacks:fn:deposit\\") != null; }")
# 0.2.9 (tools/wardrobe_0_2_9_patch.py 1): supply:fn:claims {UUID, String id} (SkyyCooking 0.1.11) - TRUE only for Boolean.TRUE (the Flask /
# Pouch takes that id now); missing / bad uuid / a Throwable = FALSE (warned once) = 0.2.8; memo = one ask per distinct id per pass
M(brg, r"""
public static boolean claimed(String uuid, String id, java.util.HashMap memo) {
  if (uuid == null || uuid.length() == 0 || id == null) return false;
  if (memo != null) { Object o = memo.get(id); if (o instanceof Boolean) return ((Boolean) o).booleanValue(); }
  boolean r = false;
  java.util.function.Function f = @PKG@.WdLog.fn("supply:fn:claims");
  if (f != null) {
    try { r = Boolean.TRUE.equals(f.apply(new Object[] { java.util.UUID.fromString(uuid), id })); }
    catch (Throwable t) { r = false; @PKG@.WdLog.warnOnce("supply:claims", "supply:fn:claims failed (logged once; Deposit all puts those items in Requip as before): " + t); }
  }
  if (memo != null) memo.put(id, Boolean.valueOf(r));
  return r;
}""")\n''')
P.rep('''  java.util.ArrayList out = new java.util.ArrayList();
  java.util.HashMap kinds = new java.util.HashMap();
  int[] add = new int[2];
  for (int o = 0; o < secs.length; o++) {''', '''  java.util.ArrayList out = new java.util.ArrayList();
  java.util.HashMap kinds = new java.util.HashMap();
  int[] add = new int[2];
  java.util.HashMap sup = new java.util.HashMap();   // 0.2.9: supply:fn:claims answers, one ask per id in this pass
  for (int o = 0; o < secs.length; o++) {''')
P.rep('''        if (o instanceof Integer && ((Integer) o).intValue() > 0) { keep.put(kk, Integer.valueOf(((Integer) o).intValue() - 1)); continue; }
      }
      @PKG@.WdMove m = depMove(d, cs, i, s, kinds, add, why);''', '''        if (o instanceof Integer && ((Integer) o).intValue() > 0) { keep.put(kk, Integer.valueOf(((Integer) o).intValue() - 1)); continue; }
      }
      // 0.2.9 (FP1 review LOW): eating beats storing - a plain storage / backpack stack the Potion Flask / Food Pouch claim stays for their
      // auto-fill (as SkyySacks 0.8.18); the hotbar / metadata stacks and auto-store (never food) as before
      if (!auto && (i == 2 || i == 3) && (x.getMetadata() == null || x.getMetadata().isEmpty()) && @PKG@.WdBridge.claimed(d.uuid, x.getItemId(), sup)) {
        why.add("the Potion Flask / Food Pouch takes your " + @PKG@.WdCodec.pretty(x.getItemId()));
        continue;
      }
      @PKG@.WdMove m = depMove(d, cs, i, s, kinds, add, why);''')
assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0, "0.2.9 adds no command / system"
P.finish()

# ====================================================================================================================== THE TEST
T = Patch(os.path.join(HERE, "test_skyywardrobe_0.2.8.py"), os.path.join(HERE, "test_skyywardrobe_0.2.9.py"), "test")
assert T.has('VERSION = "0.2.8"\n') and not T.has("supply:fn:claims")
T.rep('"""Harness for SkyyWardrobe 0.2.8 (', '''"""Harness for SkyyWardrobe 0.2.9 (tools/wardrobe_0_2_9_patch.py; FP1 review LOW: Deposit all leaves claimed food / potions).
Derived from test_skyywardrobe_0.2.8.py: EVERY 0.2.8 section runs again on the 0.2.9 jar, plus:
  RF  (inside X, after FP) a supply:fn:claims stand-in (bread + health potions claimed): Deposit all (+ deposit.hotbar) leaves the plain
      claimed storage + backpack stacks (the REPRO: 0.2.8 pooled them), takes the unclaimed potion, the helmet, a metadata bread and the
      hotbar bread; one ask per distinct id; a single Deposit click of claimed bread still goes in; claims answering FALSE / a bad answer /
      throwing (no exception escapes) / missing = as 0.2.8; auto-store unchanged; conservation + exactly once after every step
  C   class compare 0.2.8 -> 0.2.9 (--base): no class added; WdBridge + claimed only (depAllSkip: body)
  Repro: python SkyyWardrobe/test_skyywardrobe_0.2.9.py --jar SkyyWardrobe/SkyyWardrobe-0.2.8.jar  -> RF fails (the claimed food is pooled)
The 0.2.8 harness text follows:
Harness for SkyyWardrobe 0.2.8 (''')
T.rep('VERSION = "0.2.8"\n', 'VERSION = "0.2.9"\n')
T.rep('BASE = os.path.abspath(arg("--base", os.path.join(HERE, "SkyyWardrobe-0.2.7.jar")))  # 0.2.8: the class compare (the SET pin)',
      'BASE = os.path.abspath(arg("--base", os.path.join(HERE, "SkyyWardrobe-0.2.8.jar")))  # 0.2.9: the class compare (the SET pin)')
T.rep('SCRATCH = os.path.abspath(arg("--dir", os.path.join(TOOLS, "dev", "scratch", "fp1", "sackswd", "w028")))',
      'SCRATCH = os.path.abspath(arg("--dir", os.path.join(TOOLS, "dev", "scratch", "reqfood", "w029")))')
RF_TEST = r'''
        # ============================================================ RF 0.2.9 Deposit all leaves what the Potion Flask / Food Pouch claim
        from jpype import JImplements, JOverride

        @JImplements("java.util.function.Function")
        class ClaimFn(object):
            """SkyyCooking 0.1.11's supply:fn:claims contract: Object[] {UUID, String id} -> Boolean (TRUE = the Flask / Pouch takes it now)"""
            def __init__(self):
                self.ids, self.calls, self.mode = set(), [], "ok"

            @JOverride
            def apply(self, a):
                self.calls.append((str(a[0]), str(a[1])))
                if self.mode == "boom":
                    raise JClass("java.lang.IllegalStateException")("claims boom")
                if self.mode == "odd":
                    return JClass("java.lang.String")("yes")
                return JClass("java.lang.Boolean").valueOf(str(a[1]) in self.ids)
        CF = ClaimFn()
        CF.ids = {"Food_Bread", "Potion_Health"}
        br.put("supply:fn:claims", CF)
        Rae = W.player("00000000-0000-0000-0000-0000000000f2", "Rae")
        kR = str(Rae.u)
        setc(Rae.sto, 0, stack("Food_Bread", 10))
        setc(Rae.sto, 1, stack("Potion_Health", 4))
        setc(Rae.sto, 2, stack("Potion_Mana", 3))
        setc(Rae.sto, 3, stack("Armor_Iron_Head", 1, gdoc("rare", 7)))
        setc(Rae.sto, 4, stack("Food_Bread", 1, '{"Skyy_Test": {"note": "a metadata bread"}}'))
        setc(Rae.bak, 0, stack("Food_Bread", 5))
        setc(Rae.hot, 4, stack("Food_Bread", 2))
        baseR, _ = census(Rae)
        Cfg.DEP_HOT = True
        rr = run(Rae, 7)
        Cfg.DEP_HOT = False
        dR = Store.get(kR, Rae.u)
        poolR = sorted((str(e_.itemId()), int(e_.count) if e_.kind else 1) for e_ in list(dR.entries.values()))
        K.check(getc(Rae.sto, 0) is not None and str(getc(Rae.sto, 0).getItemId()) == "Food_Bread" and int(getc(Rae.sto, 0).getQuantity()) == 10
                and getc(Rae.sto, 1) is not None and int(getc(Rae.sto, 1).getQuantity()) == 4
                and getc(Rae.bak, 0) is not None and int(getc(Rae.bak, 0).getQuantity()) == 5,
                "RF REPRO: Deposit all leaves the claimed bread (storage 10 + backpack 5) and health potions (4) for the Flask / Pouch (0.2.8 pooled them) (%s; pool %s)" % (rr, poolR))
        K.check(getc(Rae.sto, 2) is None and getc(Rae.sto, 3) is None and getc(Rae.sto, 4) is None and getc(Rae.hot, 4) is None
                and len(ent_by_id(dR, "Potion_Mana")) == 1 and len(ent_by_id(dR, "Armor_Iron_Head")) == 1 and len(ent_by_id(dR, "Food_Bread")) == 2
                and not ent_by_id(dR, "Potion_Health"),
                "RF the unclaimed potion, the helmet, the metadata bread and the HOTBAR bread go in as before (pool %s)" % poolR)
        K.check(rr.startswith("+Deposited 4 stacks (3 stayed out: the Potion Flask / Food Pouch takes your"), "RF the answer names what stayed (%s)" % rr)
        ids_asked = [c_[1] for c_ in CF.calls]
        K.check(sorted(ids_asked) == sorted(set(ids_asked)) and set(ids_asked) == {"Food_Bread", "Potion_Health", "Potion_Mana"}
                and all(c_[0] == kR for c_ in CF.calls),
                "RF one supply:fn:claims ask per distinct plain storage / backpack id, with the player's uuid (%s)" % CF.calls)
        cR, dR = census(Rae)
        K.check(cR == baseR and not once(Rae, dR), "RF conservation + exactly once (after the skip)")
        # every claimed stack again: still left (a second press changes nothing)
        rr2 = run(Rae, 7)
        K.check(rr2.startswith("-Nothing could go in: the Potion Flask / Food Pouch takes your") and int(getc(Rae.sto, 0).getQuantity()) == 10,
                "RF a second Deposit all with only claimed stacks left moves nothing (%s)" % rr2)
        # the single Deposit click is an explicit choice: the claimed bread goes in
        r6 = run(Rae, 6, 0, "2:0")
        K.check(r6.startswith("+Into Requip: Food_Bread x10") and getc(Rae.sto, 0) is None, "RF a single Deposit click of claimed bread still puts it in (%s)" % r6)
        # claims answering FALSE (full / auto-fill off), a non-Boolean answer, a throwing claims, no key: as 0.2.8
        CF.ids = set()
        CF.calls = []
        setc(Rae.sto, 0, stack("Food_Bread", 6))
        baseR, _ = census(Rae)
        r7a = run(Rae, 7)
        K.check(r7a.startswith("+Deposited 3 stacks") and getc(Rae.sto, 0) is None and getc(Rae.sto, 1) is None and getc(Rae.bak, 0) is None,
                "RF claims FALSE (the Pouch is full / off): Deposit all takes them as 0.2.8 (%s)" % r7a)
        cR, dR = census(Rae)
        K.check(cR == baseR and not once(Rae, dR), "RF conservation + exactly once (claims FALSE)")
        for mode_ in ("odd", "boom", "gone"):
            setc(Rae.sto, 0, stack("Food_Bread", 3))
            setc(Rae.bak, 1, stack("Potion_Health", 2))
            CF.ids = {"Food_Bread", "Potion_Health"}
            CF.mode = mode_
            if mode_ == "gone":
                br.remove("supply:fn:claims")
            baseR, _ = census(Rae)
            rm = run(Rae, 7)
            K.check(rm.startswith("+Deposited 2 stacks") and getc(Rae.sto, 0) is None and getc(Rae.bak, 1) is None,
                    "RF claims %s: no exception escapes, Deposit all as 0.2.8 (%s)" % (mode_, rm))
            cR, dR = census(Rae)
            K.check(cR == baseR and not once(Rae, dR), "RF conservation + exactly once (claims %s)" % mode_)
        CF.mode = "ok"
        K.check(not br.containsKey("supply:fn:claims"), "RF the stand-in is gone again (later sections run as 0.2.8)")
'''
T.rep('''        K.check(cF == baseF and not once(Fay, dF), "FP conservation + exactly once")\n''',
      '''        K.check(cF == baseF and not once(Fay, dF), "FP conservation + exactly once")\n''' + RF_TEST)
T.rep('''    K.check(not removed and added == [], "C 0.2.7 -> 0.2.8: no class added or removed (%s / %s)" % (removed, added))''',
      '''    K.check(not removed and added == [], "C 0.2.8 -> 0.2.9: no class added or removed (%s / %s)" % (removed, added))''')
T.rep('''    K.check(real == ["WdCfg"] and changed["WdCfg"] == {"-": 0, "+": 1} and "builtinKeep(Ljava/lang/String;)Z" in new[PKG + "WdCfg"],
            "C (0.2.8) only WdCfg gains a member (+ builtinKeep); keep / classify: bodies only: %s %s" % (real, changed))''',
      '''    K.check(real == ["WdBridge"] and changed["WdBridge"] == {"-": 0, "+": 1}
            and "claimed(Ljava/lang/String;Ljava/lang/String;Ljava/util/HashMap;)Z" in new[PKG + "WdBridge"],
            "C (0.2.9) only WdBridge gains a member (+ claimed); depAllSkip: body only: %s %s" % (real, changed))''')
T.finish()
